import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"22、【賁】 離下艮上","description":"周易口訣義 - 22、【賁】 離下艮上","frontmatter":{"title":"22、【賁】 離下艮上","description":"周易口訣義 - 22、【賁】 離下艮上"},"headers":[],"relativePath":"classics/koujueyi/024.md","filePath":"classics/koujueyi/024.md"}'),r={name:"classics/koujueyi/024.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_22、【賁】-離下艮上" tabindex="-1">22、【賁】 離下艮上 <a class="header-anchor" href="#_22、【賁】-離下艮上" aria-label="Permalink to “22、【賁】 離下艮上”">​</a></h1><p>彖曰：「賁亨」，柔來而文剛，故「亨」。分剛上而文柔，故「小利有攸往」，天文也；文明以止，人文也。觀乎天文，以察時變；觀乎人文，以化成天下。</p><p>象曰：山下有火，賁。君子以明庶政，無敢折獄。</p><p>初九：賁其趾，舍車而徒。</p><p>象曰：「舍車而徒」，義弗乘也。</p><p>六二：賁其須。</p><p>象曰：「賁其須」，與上興也。</p><p>九三：賁如濡如，永貞吉。</p><p>象曰：「永貞」之「吉」，終莫之陵也。</p><p>六四：賁如皤如，白馬翰如，匪寇婚媾。</p><p>象曰：六四當位，疑也。「匪寇婚媾」，終無尤也。</p><p>六五：賁於丘園，束帛戔戔，吝，終吉。</p><p>象曰：六五之「吉」，有喜也。</p><p>上九：白賁，無咎。</p><p>象曰：「白賁無咎」，上得志也。</p><p>解讀</p><p>「賁亨，小利有攸往」者，賁，飾也，以剛柔交雜而相文飾也。象曰：山下有火，賁。王廙雲：「山下有火，文明相照。」夫山之為體，層峰峻嶺，巖巒峭麗，參差被日光照耀，如以雕飾而見文章，賁之象也。君子以明庶政，無敢折獄。庶，眾也；敢，果也；折，斷也。君子以明鑑之德，必須審察，為眾庶之政，無直果敢，折斷獄訟，當審慎用刑也。</p><p>「初九，賁其趾，舍車而徒」者，趾，足也；處無位之地，不尚華侈，所飾在於足趾，故曰「賁其趾」；以其執志耿介，不乘不義之車，而從有義徒步，故曰「舍車而徒」也。</p><p>「六二，賁其須」，須，須也。與三相近，情意相得，以下親上，猶如須之附面，修其所理，隨之興動，故小象雲「與上興也」。</p><p>「九三，賁如濡如，永貞吉」者，與二相得，以飾以潤，故曰「賁如濡如」也；以其非應相親，永保其正，物莫能犯，故曰「永貞吉」也。</p><p>「六四，賁如皤如，白馬翰如，匪寇婚媾」者，四應在初，被三隔礙，志唯猶豫，或文或素，故曰「賁如皤如」，質素也；既不得前進，但鮮潔其馬翰如，徘徊以待之矣，故曰「白馬翰如」也。若非九三與己為寇難，即與初已為媾婚，故曰「匪寇婚媾」也。</p><p>「六五，賁於丘園，束帛戔戔。吝終吉」者，處得尊位，為飾之主，不尚華飾，所賁質素，故其致飾如似丘園。丘園所生草木，質素而已，則不縻費國之盈盛，乃束帛珍寶戔戔眾多，故曰「賁於丘園，束帛戔戔」。若能儉而約侈，費用得宜，處約之吝，乃得終吉，故曰「吝終吉」也。</p><p>上九：白賁，無咎者，處飾之終，終乃反素矣。他人以色為飾，而我以素為飾，守志任真，得其夲性，何咎之有哉！</p>',23)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
